{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Renewal Memberships — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfa;--muted:#667085;--brand:#7a5cff;--accent:#ffb86b;--card:#fff;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,'Helvetica Neue',Arial;line-height:1.45;margin:0;background:linear-gradient(180deg,var(--bg),#f5f7fb);color:#0f1724}
    header{display:flex;align-items:center;justify-content:space-between;padding:24px 28px;background:transparent}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;background:linear-gradient(135deg,var(--brand),#9d7bff);color:white;font-weight:700}
    .hero{padding:40px 28px 32px;display:grid;grid-template-columns:1fr 360px;gap:24px;align-items:start}
    .lead{background:var(--card);padding:22px;border-radius:12px;box-shadow:0 6px 18px rgba(12,20,40,0.06)}
    h1{margin:0 0 6px;font-size:20px}
    p.lead-desc{margin:0;color:var(--muted)}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.85),var(--card));padding:18px;border-radius:12px;box-shadow:0 6px 24px rgba(12,20,40,0.06)}
    .price-title{font-weight:700;font-size:18px;margin:0 0 6px}
    .price-amount{font-size:28px;color:var(--brand);margin:0}
    .benefit{display:flex;gap:10px;align-items:flex-start;margin:12px 0}
    .btn-primary{display:inline-block;padding:10px 14px;background:var(--brand);color:white;border-radius:10px;text-decoration:none;font-weight:700}
    .tiers{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:18px}
    .tier{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 8px 20px rgba(12,20,40,0.06)}
    .tier h3{margin:0 0 6px}
    .small{font-size:13px;color:var(--muted)}
    footer{padding:28px;color:var(--muted);font-size:13px}
    .muted-block{padding:12px;border-radius:10px;background:rgba(250,250,252,0.8);margin-top:12px}
    /* blend builder compact */
    .blend-builder{margin-top:12px;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,250,240,0.6),rgba(255,255,255,0.6))}
    label{display:block;font-weight:600;margin:10px 0 6px}
    select,input[type=range]{width:100%}
    .blend-output{margin-top:12px;padding:10px;border-radius:8px;background:#fff;border:1px solid #eff2fb}
    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(6,6,8,0.45);display:none;align-items:center;justify-content:center;padding:20px}
    .modal{background:var(--card);max-width:720px;width:100%;border-radius:12px;padding:18px}
    .modal.show{display:block}
    .exercise-steps{display:flex;flex-direction:column;gap:12px}
    .step{padding:12px;border-radius:8px;background:linear-gradient(90deg,#fff,#fbfbff)}
    /* tiny responsive */
    @media(max-width:820px){.hero{grid-template-columns:1fr;}.modal{max-width:520px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">Aro</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="pricing.html">Plans</a>
      <a href="about.html">About</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="lead">
        <h1>Memberships designed for steady sensory rhythms</h1>
        <p class="lead-desc">Monthly access to small-group guiding, seasonal single-note blends, and a curated portability kit — crafted to gently support routines and intention. Safety-first, non-medical supportive practices.</p>
        <div class="tiers">
          <div class="tier">
            <h3>Essentials Circle</h3>
            <p class="small">For steady maintenance — monthly introductory guidance and one seasonal blend.</p>
            <p class="price-amount">$18/mo</p>
            <div style="margin-top:10px"><a class="btn-primary" href="{{PRIMARY_CTA_URL}}">Join Essentials</a></div>
          </div>
          <div class="tier">
            <h3>Presence Cohort</h3>
            <p class="small">Guided monthly session + blend customization + members-only notes.</p>
            <p class="price-amount">$48/mo</p>
            <div style="margin-top:10px"><a class="btn-primary" href="{{PRIMARY_CTA_URL}}">Enter Presence</a></div>
          </div>
          <div class="tier">
            <h3>Anchor Circle</h3>
            <p class="small">Priority booking, quarterly check-ins, and a personalized blend sent annually.</p>
            <p class="price-amount">$120/mo</p>
            <div style="margin-top:10px"><a class="btn-primary" href="{{PRIMARY_CTA_URL}}">Apply to Anchor</a></div>
          </div>
        </div>
        <div class="muted-block small">All plans include access to our gentle guided exercise library and the blend builder tool. Billing and cancellations are managed through your account. Reach us at {{EMAIL}} for questions.</div>
      </div>

      <aside class="panel">
        <div class="price-title">Try a sample: micro-custom blend</div>
        <div class="small">Pick a primary mood and see a safe dilution guide plus a printable blend card you can use at home.</div>

        <div class="blend-builder" aria-live="polite">
          <label for="vibe">Choose a vibe</label>
          <select id="vibe">
            <option value="calm">Calm & unbusy</option>
            <option value="focus">Clear focus</option>
            <option value="lift">Gentle uplift</option>
            <option value="sleep">Soft sleep support</option>
          </select>

          <label for="size">Make for (bottle)</label>
          <select id="size">
            <option value="10">10 ml</option>
            <option value="15">15 ml</option>
            <option value="30">30 ml</option>
          </select>

          <label for="strength">Intensity</label>
          <input id="strength" type="range" min="1" max="3" value="2">

          <div class="blend-output" id="blendOutput">Select options to preview blend and dilution guide.</div>
          <div style="margin-top:10px"><button class="btn-primary" id="saveBlend">Save this card</button></div>
        </div>

        <hr style="margin:12px 0;border-color:#f0f3ff">
        <div>
          <button class="btn-primary" id="openExercise">Try a short practice</button>
          <div class="small" style="margin-top:8px">A 3–6 minute guided breath/journal option to center before use.</div>
        </div>
      </aside>
    </section>

    <section style="padding:20px 28px">
      <h2 style="margin:0 0 8px">Membership differences, in plain terms</h2>
      <p class="small">Our groups emphasize steady habits and low-friction rituals — each plan has clear, safety-forward boundaries about aromatherapy use. Full FAQ available in the About page.</p>
    </section>
  </main>

  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap">
      <div>Questions? Call <strong>{{PHONE}}</strong> or email <strong>{{EMAIL}}</strong></div>
      <div style="font-weight:700">Serving {{CITY}}, {{STATE}}</div>
    </div>
  </footer>

  <!-- modal and scripts -->
  <div class="modal-backdrop" id="modalBackdrop" role="dialog" aria-modal="true">
    <div class="modal" role="document">
      <h3 id="modalTitle">Guided Practice</h3>
      <div class="exercise-steps" id="exerciseSteps">
        <!-- steps injected -->
      </div>
      <div style="display:flex;gap:8px;margin-top:12px;justify-content:flex-end">
        <button id="closeModal" style="padding:8px 12px;border-radius:8px">Close</button>
      </div>
    </div>
  </div>

  <script>
    // Inline SVG pattern as a CSS background (unique) applied programmatically if needed
    (function(){
      var svg = encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="120" height="120" viewBox="0 0 120 120"><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="#f6f2ff"/><stop offset="1" stop-color="#fff"/></linearGradient></defs><rect width="120" height="120" fill="url(#g)"/><g fill-opacity="0.06"><circle cx="30" cy="30" r="14" fill="#7a5cff"/><circle cx="90" cy="60" r="22" fill="#ffb86b"/><rect x="8" y="80" width="40" height="18" rx="6" fill="#7a5cff"/></g></svg>');
      document.body.style.backgroundImage = 'url("data:image/svg+xml,'+svg+'")';
      document.body.style.backgroundRepeat = 'repeat';
    })();

    // Blend builder logic
    (function(){
      var vibes = {
        calm:{notes:['Lavender','Sweet Marjoram','Chamomile'],base:'Jojoba',recommendation:'For a 10 ml bottle: 1%–2% dilution; patch test first.'},
        focus:{notes:['Rosemary','Basil','Lemon'],base:'Fractionated Coconut Oil',recommendation:'For a 10 ml bottle: 0.5%–1.5% dilution; avoid eyes.'},
        lift:{notes:['Sweet Orange','Grapefruit','Bergamot'],base:'Sweet Almond Oil',recommendation:'For a 10 ml bottle: 1%–2% dilution; phototoxic caution for bergamot.'},
        sleep:{notes:['Cedarwood','Lavender','Marjoram'],base:'Jojoba',recommendation:'For a 10 ml bottle: 0.5%–2% dilution; consult pregnancy notes.'}
      };

      function render(){
        var vibe = document.getElementById('vibe').value;
        var size = parseInt(document.getElementById('size').value,10);
        var strength = parseInt(document.getElementById('strength').value,10);
        var map = {1:0.5,2:1,3:2}; // percent multipliers
        var basePerc = 1; // baseline percent
        var percent = basePerc * map[strength];
        // compute drops ~ 20 drops per ml
        var dropsPerMl = 20;
        var totalDrops = Math.round(size * dropsPerMl * (percent/100));
        var notes = vibes[vibe].notes;
        // split drops among notes
        var cardNotes = notes.map(function(n,i){return {name:n,drops:Math.max(1,Math.round(totalDrops/notes.length))};});
        var out = '<strong>Blend preview — '+vibe.replace(/\b\w/g,function(l){return l.toUpperCase();})+'</strong>';
        out += '<div style="margin-top:6px;color:var(--muted);font-size:14px">Bottle: '+size+' ml • Target dilution: '+percent+'% • Estimated drops: '+totalDrops+'</div>';
        out += '<div style="margin-top:8px">';
        cardNotes.forEach(function(n){out += '<div style="padding:6px 8px;border-radius:8px;background:#fff;margin-bottom:6px"><strong>'+n.name+'</strong><div class="small" style="margin-top:4px">'+n.drops+' drops</div></div>';});
        out += '</div>';
        out += '<div class="small" style="margin-top:8px">Carrier: '+vibes[vibe].base+'<br>'+vibes[vibe].recommendation+'</div>';
        out += '<div class="small" style="margin-top:6px;color:#a33">Safety notes: Avoid undiluted application; keep oils away from pets; if pregnant/under medical care consult provider. Patch test on inner forearm before regular use.</div>';
        document.getElementById('blendOutput').innerHTML = out;
      }

      document.getElementById('vibe').addEventListener('change',render);
      document.getElementById('size').addEventListener('change',render);
      document.getElementById('strength').addEventListener('input',render);
      document.getElementById('saveBlend').addEventListener('click',function(){
        var el = document.getElementById('blendOutput');
        alert('Blend saved to your browser notes. You can copy this card for later use.');
      });
      render();
    })();

    // Guided exercise modal (breath + short journaling)
    (function(){
      var modal = document.getElementById('modalBackdrop');
      var stepsEl = document.getElementById('exerciseSteps');
      var close = document.getElementById('closeModal');
      var open = document.getElementById('openExercise');
      var sequence = [
        {title:'Set an intention',desc:'Sit comfortably. Decide on a single short intention for this moment (e.g. "soften" or "arrive"). Type or speak it to yourself.'},
        {title:'3-minute paced breathing',desc:'Breathe in for 4, hold 3, out for 6. Repeat 6 times. Notice the steady pace — no force.'},
        {title:'Reflection prompt',desc:'Spend 60 seconds noting one small detail you noticed in your body or thoughts. If journaling, write one sentence.'},
        {title:'Close',desc:'Take a final deep breath and gently open your eyes. Carry your intention softly with you.'}
      ];

      function show(){
        stepsEl.innerHTML = '';
        sequence.forEach(function(s,i){
          var div = document.createElement('div');
          div.className = 'step';
          div.innerHTML = '<strong>'+s.title+'</strong><div class="small" style="margin-top:6px">'+s.desc+'</div>';
          stepsEl.appendChild(div);
        });
        modal.style.display = 'flex';
      }
      open.addEventListener('click',show);
      close.addEventListener('click',function(){modal.style.display='none'});
      modal.addEventListener('click',function(e){if(e.target===modal)modal.style.display='none'});
    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — Practitioner's Ethos</title>
  <style>
    :root{--bg:#fff8f2;--ink:#0b1220;--muted:#6b7280;--accent:#7a5cff}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none}
    .hero{padding:28px 24px;background:linear-gradient(180deg,#fff,#fffaf6);display:grid;grid-template-columns:1fr 320px;gap:20px}
    .card{background:white;border-radius:12px;padding:18px;box-shadow:0 8px 20px rgba(12,20,40,0.06)}
    h1{margin:0 0 8px}
    .meta{color:var(--muted);font-size:14px}
    .faq{margin-top:12px}
    .faq dt{font-weight:700;margin-top:10px}
    .faq dd{margin:6px 0 12px;color:var(--muted)}
    .cta{display:flex;gap:10px;margin-top:12px}
    .btn{padding:10px 12px;border-radius:10px;text-decoration:none}
    .btn.secondary{background:transparent;border:1px solid #e6e9f2;color:var(--accent)}
    .pattern-bar{height:12px;background:linear-gradient(90deg,#fff0,#fff0)}
    .blend-sample{margin-top:12px;padding:10px;border-radius:8px;background:linear-gradient(90deg,#fff,#fffaf2)}
    footer{padding:22px 24px;color:var(--muted);font-size:13px}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:48px;height:48px;background:linear-gradient(135deg,#ffd4a3,#7a5cff);border-radius:10px;display:grid;place-items:center;color:white;font-weight:700">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div class="meta">A gentle approach to aromatic practices</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Main</a>
      <a href="services.html">Services</a>
      <a href="blends.html">Blends</a>
      <a href="pricing.html">Memberships</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <article class="card">
        <h1>Practitioner philosophy</h1>
        <p class="meta">We work with aroma as a context for small, repeatable practices that people can fold into daily life. Our offerings aim to support presence and simple routines, not to treat medical conditions.</p>

        <p style="margin-top:12px">Sessions and resources emphasize informed, safety-first choices. Every recommendation is accompanied by dilution guidance, advice about pets and pregnancy, and a simple patch test procedure. We invite curiosity and care.</p>

        <div class="faq" aria-labelledby="faqTitle">
          <h3 id="faqTitle">Common questions</h3>
          <dl>
            <dt>How do I do a patch test?</dt>
            <dd>Apply a small diluted drop to the inside of the forearm, cover for 24 hours, and check for irritation. If redness or discomfort occurs, discontinue use.</dd>
            <dt>What dilution is safe?</dt>
            <dd>Typical home dilutions are 0.5%–2% for adults depending on sensitivity and purpose. Our materials always include a clear dilution guide for each suggested blend size.</dd>
            <dt>What about pets or pregnancy?</dt>
            <dd>Some essential oils may pose risks to pets or during pregnancy. We include warnings and suggest consulting a provider in pregnancy or when pets are in the home. Never apply oils directly to a pet without veterinary guidance.</dd>
            <dt>Are these medical treatments?</dt>
            <dd>No — our guidance uses phrasing such as “may support” and is not a substitute for medical care.</dd>
          </dl>
        </div>

        <div style="margin-top:12px" class="cta">
          <a class="btn" href="{{PRIMARY_CTA_URL}}">Start a membership</a>
          <a class="btn secondary" href="book.html">Book a consult</a>
        </div>
      </article>

      <aside>
        <div class="card">
          <h3 style="margin:0 0 8px">Quick sample</h3>
          <div class="blend-sample">
            <strong>Mini blend: steady focus</strong>
            <div class="meta" style="margin-top:6px">Rosemary + Lemon — 10 ml @ 1% (approx. 2 drops)</div>
            <div style="margin-top:8px" class="small">Notes: avoid contact with eyes; patch test; keep out of reach of children and pets.</div>
          </div>

          <div style="margin-top:12px">
            <button class="btn" id="openExercise2">Try 3-minute centering</button>
          </div>
        </div>

        <div style="margin-top:12px" class="card">
          <h4 style="margin:0">Credentials</h4>
          <p class="small" style="margin-top:8px">Certified aromatherapist with clinical safety training and community-group facilitation experience.</p>
        </div>
      </aside>
    </section>

    <section style="padding:22px 24px">
      <h3>More on safety</h3>
      <p class="small">We provide clear labeling for blends, suggest lowest effective dilutions, and offer alternatives (inhalation only via a personal inhaler or diffuser pad) for those who prefer not to use topical applications.</p>
    </section>
  </main>

  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap">
      <div>Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • {PHONE}</div>
      <div class="meta">Serving {{CITY}}, {{STATE}}</div>
    </div>
  </footer>

  <!-- Modal + scripts reused inline -->
  <div id="modal2" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,0.45);align-items:center;justify-content:center;padding:20px">
    <div style="background:white;padding:18px;border-radius:10px;max-width:520px;width:100%">
      <h4>Centered Breath</h4>
      <div id="steps2"></div>
      <div style="text-align:right;margin-top:12px"><button id="close2">Close</button></div>
    </div>
  </div>

  <script>
    // small guided exercise (simple variant)
    (function(){
      var open = document.getElementById('openExercise2');
      var modal = document.getElementById('modal2');
      var steps = document.getElementById('steps2');
      var close = document.getElementById('close2');
      var seq = [
        {t:'Notice',d:'Take an upright seat. Notice points of contact with your chair.'},
        {t:'Breathe',d:'Three slow breaths. In for 4, out for 6.'},
        {t:'Name',d:'Name one intention word briefly.'}
      ];
      open.addEventListener('click',function(){steps.innerHTML='';seq.forEach(function(s){var el=document.createElement('div');el.style.padding='10px 0';el.innerHTML='<strong>'+s.t+'</strong><div style="color:#6b7280">'+s.d+'</div>';steps.appendChild(el)});modal.style.display='flex'});
      close.addEventListener('click',function(){modal.style.display='none'});
      modal.addEventListener('click',function(e){if(e.target===modal)modal.style.display='none'});
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve a Session</title>
  <style>
    :root{--card:#fff;--muted:#64748b;--accent:#7a5cff}
    *{box-sizing:border-box}
    body{font-family:Inter,system-ui,Arial;margin:0;background:#fbfcfe;color:#071130}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    .wrap{max-width:980px;margin:18px auto;padding:0 18px}
    .grid{display:grid;grid-template-columns:1fr 340px;gap:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 8px 24px rgba(8,16,40,0.06)}
    label{display:block;margin-top:10px;font-weight:700}
    input,select,textarea{width:100%;padding:10px;margin-top:6px;border-radius:8px;border:1px solid #eef2ff}
    .btn{display:inline-block;padding:10px 14px;border-radius:10px;background:var(--accent);color:white;text-decoration:none;border:none}
    .note{font-size:13px;color:var(--muted)}
    .avail{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
    .slot{padding:8px 10px;border-radius:8px;border:1px solid #eef2ff;background:#fff}
    footer{padding:18px;color:var(--muted);font-size:13px}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,#7a5cff,#ffd4a3);display:grid;place-items:center;color:white;font-weight:700">A</div>
      <div style="font-weight:700">Book with {{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Create</a>
      <a href="pricing.html">Plans</a>
      <a href="about.html">About</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <div class="wrap">
    <div class="grid">
      <div class="card">
        <h2 style="margin:0 0 8px">Reserve a consult or group session</h2>
        <p class="note">Choose the format and we’ll follow up with a confirmation and pre-visit guidance. All sessions emphasize safety and non-medical supportive practices.</p>

        <form id="bookingForm" onsubmit="return false;">
          <label for="type">Session type</label>
          <select id="type">
            <option value="intro">30-min Intro (one-on-one)</option>
            <option value="deep">60-min Consultation</option>
            <option value="group">Small group practice (monthly)</option>
          </select>

          <label for="name">Your name</label>
          <input id="name" required>

          <label for="email">Email</label>
          <input id="email" type="email" required>

          <label for="notes">Brief notes (allergies, pregnancy, pets at home)</label>
          <textarea id="notes" rows="4" placeholder="Optional — include any conditions we should be aware of"></textarea>

          <label for="when">Preferred date</label>
          <input id="when" type="date" required>

          <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
            <button class="btn" id="submitBtn">Request booking</button>
            <div style="font-size:13px;color:var(--muted)">Or call <strong>{{PHONE}}</strong></div>
          </div>

          <div style="margin-top:12px;font-size:13px;color:var(--muted)">By requesting a booking you agree to receive scheduling messages to {{EMAIL}}. Cancellations accepted up to 24 hours before.</div>
